25:   postorderCallback: (node: compiler.TmplAstElement) => void = () => {},
26: ): void {
27:   nodes.reverse();
28:   for (let i = 0; i < nodes.length; i++) {
29:     const node = nodes[i];
30:     if (node instanceof compiler.TmplAstElement) {
31:       preorderCallback(node);
